#!/usr/bin/env python3
"""Old-link safety net for The Numbers Game site (GitHub Pages, no server redirects).

Reads data/catalogue.json (+ the frozen data/simplecast-slugs.json) and writes:
  episodes/<slug>.html           /episodes/<slug>      -> /<slug>   (old Simplecast URL)
  episodes/<slug>/index.html     /episodes/<slug>/     -> /<slug>
  episodes/<old>.html (+ /index) old Simplecast slug, where it differs from today's slug
  episodes/<old>-<token>.html    Simplecast code-suffix duplicate URLs
  episodes/index.html            /episodes/            -> /episodes  (episodes.html still wins for /episodes)
  <slug>/index.html              /<slug>/ (trailing slash) -> /<slug>  (<slug>.html still wins for /<slug>)
  listen.html, guests.html, blog.html   simple stubs for known 404s
  404.html                       smart 404: normalises the path, redirects clear matches,
                                 otherwise suggests 3 episodes; GA4 page_not_found event
  llms.txt                       plain description of the site and its URL pattern

Every stub is an instant redirect (JS location.replace keeping ?query and #hash, plus a
meta refresh fallback), noindex, with rel=canonical to the real page. No GA tag on stubs
(same rule as the epN.html short links) so the visit is counted once, on the real page.

Safe to run any number of times. It only ever deletes or overwrites files that carry the
GENERATED marker below, so it can never clobber a hand-made page.
Run from the repo root:  python3 .github/scripts/build_old_links.py
"""
import html, json, os, re, sys

SITE = "https://thenumbersgamepodcast.com.au"
GA_ID = "G-5QN0VF1L64"
MARK = "<!-- generated by .github/scripts/build_old_links.py: do not edit -->"
ROOT = os.environ.get("REPO_DIR", ".")
SIMPLE_STUBS = {  # path (no .html) -> target, only for known 404s with an obvious home
    "listen": "/",        # homepage carries the YouTube / Spotify / Apple listen buttons
    "guests": "/episodes",
    "blog": "/episodes",
}

def p(*a):
    return os.path.join(ROOT, *a)

def load(path, default=None):
    try:
        with open(p(path), encoding="utf-8") as f:
            return json.load(f)
    except FileNotFoundError:
        if default is not None:
            return default
        raise

def stub(target):
    t_attr = html.escape(target, quote=True)
    t_js = json.dumps(target)
    return (
        "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\">\n" + MARK + "\n"
        "<title>Redirecting… | The Numbers Game</title>\n"
        f"<link rel=\"canonical\" href=\"{SITE}{t_attr}\">\n"
        "<meta name=\"robots\" content=\"noindex, follow\">\n"
        f"<script>location.replace({t_js}+location.search+location.hash);</script>\n"
        f"<meta http-equiv=\"refresh\" content=\"0; url={t_attr}\">\n"
        "</head><body style=\"font-family:sans-serif;background:#12093a;color:#fff;padding:40px\">\n"
        f"This episode has moved to <a style=\"color:#7ad9a8\" href=\"{t_attr}\">{html.escape(SITE + target)}</a>.</body></html>\n"
    )

def is_generated(path):
    try:
        with open(path, encoding="utf-8", errors="ignore") as f:
            return MARK in f.read(600)
    except (FileNotFoundError, IsADirectoryError):
        return False

def write(rel, content, wanted):
    full = p(rel)
    wanted.add(os.path.normpath(full))
    if os.path.exists(full) and not is_generated(full):
        print(f"skip (hand-made file already there): {rel}", file=sys.stderr)
        return
    os.makedirs(os.path.dirname(full) or ".", exist_ok=True)
    old = None
    if os.path.exists(full):
        with open(full, encoding="utf-8") as f:
            old = f.read()
    if old != content:
        with open(full, "w", encoding="utf-8") as f:
            f.write(content)

def cleanup(wanted, slugs):
    """Remove generated files we no longer produce (e.g. a slug was renamed)."""
    removed = 0
    cands = []
    for dp, dn, fn in os.walk(p("episodes")):
        cands += [os.path.join(dp, f) for f in fn]
    for d in os.listdir(p(".")):
        f = p(d, "index.html")
        if os.path.isdir(p(d)) and os.path.exists(f):
            cands.append(f)
    for f in cands:
        f = os.path.normpath(f)
        if f not in wanted and is_generated(f):
            os.remove(f); removed += 1
            d = os.path.dirname(f)
            if d != os.path.normpath(p(".")) and not os.listdir(d):
                os.rmdir(d)
    return removed

def main():
    cat = load("data/catalogue.json")
    sc = load("data/simplecast-slugs.json", {"episodes": []}).get("episodes", [])
    live = [e for e in cat if e.get("slug") and os.path.exists(p(e["slug"] + ".html"))]
    cur = {e["slug"] for e in live}
    by_num = {e.get("episodeNumber"): e for e in live}
    reserved = {"episodes", "assets", "data", "archived", "index", "404"}

    wanted, aliases = set(), {}
    for e in live:
        s, t = e["slug"], "/" + e["slug"]
        write(f"episodes/{s}.html", stub(t), wanted)
        write(f"episodes/{s}/index.html", stub(t), wanted)
        if s not in reserved:
            write(f"{s}/index.html", stub(t), wanted)

    n_old = n_tok = 0
    for o in sc:
        e = by_num.get(o.get("episodeNumber"))
        if not e:
            continue
        t, old, tok = "/" + e["slug"], o.get("slug"), o.get("token")
        if old and old != e["slug"]:
            if old in cur:  # never steal another episode's live slug
                print(f"skip old slug {old}: it is another episode's live slug", file=sys.stderr)
            else:
                aliases[old] = e["slug"]
                write(f"episodes/{old}.html", stub(t), wanted)
                write(f"episodes/{old}/index.html", stub(t), wanted)
                n_old += 1
        if old and tok and re.fullmatch(r"[A-Za-z0-9_]{8}", tok):
            write(f"episodes/{old}-{tok}.html", stub(t), wanted)
            n_tok += 1

    write("episodes/index.html", stub("/episodes"), wanted)
    for name, target in SIMPLE_STUBS.items():
        if not os.path.exists(p(name + ".html")) or is_generated(p(name + ".html")):
            write(f"{name}.html", stub(target), wanted)

    removed = cleanup(wanted, cur)

    # ---- 404.html data (newest first) ----
    eps = sorted(live, key=lambda e: -(e.get("episodeNumber") or 0))
    data = {
        "e": [[e["slug"], e.get("title", ""), e.get("episodeNumber")] for e in eps],
        "a": aliases,
    }
    tpl_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "404.template.html")
    with open(tpl_path, encoding="utf-8") as f:
        tpl = f.read()
    blob = json.dumps(data, ensure_ascii=False, separators=(",", ":")).replace("</", "<\\/")
    out = tpl.replace("__GA_ID__", GA_ID).replace("__DATA__", blob).replace("__MARK__", MARK)
    with open(p("404.html"), "w", encoding="utf-8") as f:
        f.write(out)

    # ---- llms.txt ----
    latest = eps[:10]
    lines = [
        "# The Numbers Game",
        "",
        "> The Numbers Game is a weekly Australian podcast about finance, investment and business, hosted by accountant "
        "Jason Robinson and financial planner Nick Reilly. Each episode has its own page with the video and show notes; "
        "many also have chapters and a transcript.",
        "",
        "## URL pattern",
        f"- Home: {SITE}/",
        f"- Every episode (searchable list): {SITE}/episodes",
        f"- One episode: {SITE}/<episode-slug> (no trailing slash, no .html), e.g. {SITE}/{eps[0]['slug']}",
        f"- Old links of the form {SITE}/episodes/<slug> (from the previous Simplecast site) redirect to {SITE}/<slug>",
        f"- About the show: {SITE}/about",
        f"- Hosts: {SITE}/nick-reilly and {SITE}/jason-robinson",
        f"- Find moments inside episodes: {SITE}/adventure",
        f"- Contact: {SITE}/contact",
        f"- Sitemap: {SITE}/sitemap.xml",
        "- Podcast RSS feed: https://feeds.simplecast.com/1EHEYhtl",
        "- YouTube: https://www.youtube.com/@thenumbersgamepodcast",
        "- Spotify: https://open.spotify.com/show/41SVe1eJhucikhF3fWD3NW",
        "- Apple Podcasts: https://podcasts.apple.com/au/podcast/id1555566088",
        "",
        "## Latest episodes",
    ] + [f"- [{e.get('title','')}]({SITE}/{e['slug']})" for e in latest] + [
        "",
        f"The full list of {len(eps)} episodes is at {SITE}/episodes and in {SITE}/sitemap.xml.",
        "The Numbers Game provides general information only and does not take into account your personal objectives, financial situation or needs.",
        "",
    ]
    with open(p("llms.txt"), "w", encoding="utf-8") as f:
        f.write("\n".join(lines))

    print(f"old links: {len(live)} episodes, {n_old} renamed Simplecast slugs, {n_tok} code-suffix links, "
          f"{len(wanted)} stub files, {removed} stale removed; 404.html + llms.txt written")

if __name__ == "__main__":
    main()
